const verified = $json.users?.[0] ?? {};
const userId = verified.localId;
if (!userId) {
  throw new Error('Firebase token did not resolve to a user.');
}
if (verified.disabled === true) {
  throw new Error('This Firebase account is disabled.');
}

const body = $('Content Maker Webhook').first().json.body ?? {};
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const asUuid = (value) => UUID_RE.test(String(value ?? '')) ? String(value) : null;
const projectId = asUuid(body.project_id) ?? crypto.randomUUID();
const requestedCount = Math.min(90, Math.max(1, Number.parseInt(body.slide_count ?? '8', 10) || 8));

return [{
  json: {
    mode: body.mode === 'assistant' ? 'assistant' : 'generate',
    project_id: projectId,
    session_id: asUuid(body.session_id),
    user_id: userId,
    message: String(body.message ?? ''),
    description: String(body.description ?? ''),
    purpose: body.purpose || 'Sales',
    slide_count: requestedCount,
    style: body.style || 'modern',
    font_set: body.font_set || 'grotesk',
    palette: body.palette || 'clay',
    ratio: body.ratio || '16:9',
    slides: Array.isArray(body.slides) ? body.slides : [],
    selected_slide_id: body.selected_slide_id || null,
    messages: Array.isArray(body.messages) ? body.messages.slice(-30) : [],
    asset_context: String(body.asset_context ?? '')
  }
}];

