parameters.jsCode:
// Hard content budgets. The prompt asks the model for these; this guarantees
// them. A slide over budget is trimmed at a word boundary, so the deck can
// never render as a wall of text.
const BUDGET = {
  name: 40, eyebrow: 40, title: 70, body: 200,
  bullet: 90, bullets: 4,
  metricValue: 10, metricLabel: 30, metrics: 3,
  chart: 8, reply: 400,
};
const LAYOUTS = ['A', 'B', 'C', 'D'];
const TYPES = ['title','split','bullets','visual','metrics','services','timeline','process','chart','closing'];

function clampText(value, max) {
  const text = String(value ?? '').replace(/\s+/g, ' ').trim();
  if (text.length <= max) return text;
  const cut = text.slice(0, max);
  const lastSpace = cut.lastIndexOf(' ');
  const trimmed = lastSpace > max * 0.6 ? cut.slice(0, lastSpace) : cut;
  return trimmed.replace(/[\s,;:.\-]+$/, '');
}

function toList(value) {
  if (Array.isArray(value)) {
    return value.map((item) => (typeof item === 'string' ? item.trim() : item)).filter(Boolean);
  }
  if (typeof value === 'string') {
    return value.split(/\r?\n|[;•]|,(?=\s)/).map((part) => part.trim()).filter(Boolean);
  }
  return [];
}

function toNumbers(value) {
  return toList(value)
    .map((item) => (typeof item === 'number' ? item : Number(String(item).replace(/[^0-9.\-]/g, ''))))
    .filter((item) => Number.isFinite(item))
    .slice(0, BUDGET.chart);
}

const source = $input.first().json;
const raw = source.output ?? source.text ?? source.response?.text ?? source;
let result = raw;
if (typeof raw === 'string') {
  try {
    result = JSON.parse(raw.trim().replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim());
  } catch {
    throw new Error('Content Maker agent did not return valid JSON.');
  }
}
if (result?.output) result = result.output;
if (!result || typeof result !== 'object') {
  throw new Error('Content Maker agent returned an unusable result.');
}
if (!result.reply || !String(result.reply).trim()) {
  throw new Error('Content Maker agent returned an empty reply.');
}

const input = $('Merge Saved Context').first().json;

result.reply = clampText(result.reply, BUDGET.reply);
// The model may omit unchanged settings; fall back to what the user asked for.
result.style = result.style ?? input.style;
result.fontSet = result.fontSet ?? input.font_set;
result.palette = result.palette ?? input.palette;
result.purpose = result.purpose ?? input.purpose;
result.ratio = result.ratio ?? input.ratio;
result.generate = result.generate ?? (input.mode === 'generate');
result.rewriteSelected = result.rewriteSelected ?? 'None';

if (!Array.isArray(result.slides)) result.slides = [];
result.slides = result.slides.map((slide, index) => {
  const bullets = toList(slide.bullets)
    .slice(0, BUDGET.bullets)
    .map((item) => clampText(item, BUDGET.bullet))
    .filter(Boolean);

  const metrics = (Array.isArray(slide.metrics) ? slide.metrics : [])
    .slice(0, BUDGET.metrics)
    .map((m) => ({
      value: clampText(m?.value, BUDGET.metricValue),
      label: clampText(m?.label, BUDGET.metricLabel),
    }))
    .filter((m) => m.value || m.label);

  return {
    id: slide.id || ('slide-' + (index + 1)),
    name: clampText(slide.name, BUDGET.name) || ('Slide ' + (index + 1)),
    type: TYPES.includes(slide.type) ? slide.type : 'bullets',
    layout: LAYOUTS.includes(slide.layout) ? slide.layout : LAYOUTS[index % LAYOUTS.length],
    eyebrow: clampText(slide.eyebrow, BUDGET.eyebrow),
    title: clampText(slide.title, BUDGET.title),
    body: clampText(slide.body, BUDGET.body),
    bullets,
    metrics,
    chart: toNumbers(slide.chart),
    useImage: Boolean(slide.useImage),
  };
});

result.slideCount = result.slides.length || result.slideCount || 8;
result.generated_at = new Date().toISOString();

return [{
  json: {
    ...result,
    actions: result,
    result,
    session_id: input.session_id,
    user_id: input.user_id,
    project_id: input.project_id,
    title: result.slides[0]?.title || 'Untitled presentation'
  }
}];

const headers = $json.headers ?? {};
const raw = headers.authorization ?? headers.Authorization ?? '';
const token = String(raw).replace(/^Bearer\s+/i, '').trim();
if (!token || token.length > 8192) {
  throw new Error('Missing Firebase ID token in the Authorization header.');
}
return [{ json: { id_token: token } }];

const input = $('Verify User and Normalize').first().json;
const ownedBy = (doc) => (doc && (!doc.owner_id || doc.owner_id === input.user_id) ? doc : {});

const memory = ownedBy($('Load Account Memory').first()?.json);
const historyDoc = ownedBy($('Load Chat History').first()?.json);
const deck = ownedBy($input.first()?.json);

// Per-user prompt layers written in the background by the profile builder.
// Used as DATA only — never as instructions.
const layers = memory.prompt_layers && typeof memory.prompt_layers === 'object' ? memory.prompt_layers : {};
const deckCommand = String(layers.deck_command ?? '').slice(0, 2000);
const contentStyle = String(layers.content_style ?? '').slice(0, 2000);

const normalize = (item) => ({
  role: item?.role === 'assistant' ? 'assistant' : 'user',
  text: String(item?.text ?? '').slice(0, 8000)
});

const stored = Array.isArray(historyDoc.messages) ? historyDoc.messages : [];
const history = (stored.length ? stored : input.messages)
  .map(normalize)
  .filter((item) => item.text)
  .slice(-16);

// The user no longer has to type a brief. Fall back to their stored command,
// then to a sensible default derived from the purpose they picked.
const description = String(input.description ?? '').trim()
  || deckCommand
  || `Create a ${input.purpose || 'Sales'} presentation for this business.`;

return [{
  json: {
    ...input,
    description,
    content_style: contentStyle,
    history,
    saved_slides: Array.isArray(deck.slides) ? deck.slides : [],
    saved_theme: deck.theme ?? {},
    business_profile: memory.business_profile ?? {},
    audience_profile: memory.audience_profile ?? {},
    offer_profile: memory.offer_profile ?? {},
    brand_profile: memory.brand_profile ?? {},
    creation_preferences: memory.creation_preferences ?? {},
    memory_summary: memory.memory_summary ?? ''
  }
}];

const result = $input.first().json;
const input = $('Merge Saved Context').first().json;
const now = new Date().toISOString();

const history = [...input.history];
const last = history[history.length - 1];
if (input.message && !(last?.role === 'user' && last?.text === input.message)) {
  history.push({ role: 'user', text: input.message });
}
history.push({ role: 'assistant', text: String(result.reply) });

const messages = history.slice(-60).map((item, index) => ({
  id: `${result.project_id}-${index}`,
  role: item.role,
  text: item.text,
  created_at: now
}));

return [{
  json: {
    project_id: result.project_id,
    owner_id: result.user_id,
    workflow: 'content-maker',
    blueprint_session_id: result.session_id,
    status: 'completed',
    title: result.title,
    brief: {
      description: input.description,
      purpose: result.result?.purpose ?? input.purpose,
      slide_count: result.result?.slideCount ?? input.slide_count
    },
    slides: result.result?.slides ?? [],
    messages,
    theme: {
      style: result.result?.style ?? input.style,
      font_set: result.result?.fontSet ?? input.font_set,
      palette: result.result?.palette ?? input.palette,
      ratio: result.result?.ratio ?? input.ratio
    },
    updated_at: now
  }
}];

// Reached when the agent or the validator fails. A failed generation must
// never wipe the deck the user already has — hand their slides straight back.
let input = {};
try {
  input = $('Merge Saved Context').first().json ?? {};
} catch {
  try { input = $('Verify User and Normalize').first().json ?? {}; } catch { input = {}; }
}

const failure = $input.first()?.json ?? {};
console.log('Webinar Content recovered from a failed turn:', String(failure.error?.message ?? failure.message ?? '').slice(0, 300));

// Prefer what is on their screen, then the last saved deck. Never an empty deck.
const slides = (Array.isArray(input.slides) && input.slides.length)
  ? input.slides
  : (Array.isArray(input.saved_slides) ? input.saved_slides : []);

const result = {
  reply: "That didn't generate cleanly, so I've left your deck exactly as it was. Try again, or tell me what to change.",
  slides,
  slideCount: slides.length,
  style: input.style,
  fontSet: input.font_set,
  palette: input.palette,
  purpose: input.purpose,
  ratio: input.ratio,
  generate: false,
  rewriteSelected: 'None',
  recovered: true
};

return [{
  json: {
    ...result,
    actions: result,
    result,
    session_id: input.session_id ?? null,
    user_id: input.user_id ?? null,
    project_id: input.project_id ?? null,
    title: slides[0]?.title || 'Untitled presentation'
  }
}];
